/**
 * ================================================================
 *  PORTFOLIO RENDERING ENGINE
 *  Reads data from projects-data.js and generates all project
 *  cards automatically.
 *
 *  ⚠  Do NOT edit this file to add projects.
 *     Edit assets/js/projects-data.js instead.
 * ================================================================
 */

(function () {
  'use strict';

  /* ── Utilities ───────────────────────────────────────────── */

  /** Escape HTML special characters to prevent XSS. */
  function esc(str) {
    if (!str) return '';
    return String(str)
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;');
  }

  const STATUS_LABELS = {
    live:     'Live',
    progress: 'In Progress',
    soon:     'Coming Soon'
  };

  function statusPill(s) {
    if (!s) return '';
    const label = STATUS_LABELS[s] || s;
    return `<span class="project-status ${esc(s)}">${esc(label)}</span>`;
  }

  /* ── Shared sub-components ───────────────────────────────── */

  function renderBadges(model, accuracy, dataset) {
    let html = '<div class="project-badges">';
    if (model)    html += `<span class="badge model">${esc(model)}</span>`;
    if (accuracy) html += `<span class="badge accuracy">${esc(accuracy)}</span>`;
    if (dataset)  html += `<span class="badge dataset">${esc(dataset)}</span>`;
    html += '</div>';
    return html;
  }

  const LINK_DEFS = [
    { key: 'github', icon: 'fab fa-github',      label: 'GitHub',    cls: 'github' },
    { key: 'dataset',  icon: 'fas fa-database',   label: 'Dataset',     cls: 'dataset'  },
    { key: 'demo',   icon: 'fas fa-play-circle', label: 'Live Demo', cls: 'demo'   },
    { key: 'docs',   icon: 'fas fa-file-alt',    label: 'Docs',      cls: 'docs'   },
  ];

  function renderLinks(links) {
    let html = '<div class="project-links">';
    for (const def of LINK_DEFS) {
      const url      = links ? links[def.key] : '';
      const disabled = url ? '' : ' disabled';
      const href     = url ? esc(url) : '#';
      const rel      = url ? ' target="_blank" rel="noopener noreferrer"' : '';
      html += `<a href="${href}"${rel} class="link-btn ${def.cls}${disabled}">
        <i class="${def.icon}"></i>${def.label}
      </a>`;
    }
    html += '</div>';
    return html;
  }

  /* ── Featured project card ───────────────────────────────── */

  function renderFeatured(p) {
    if (!p) return '';

    let mediaHtml = '';
    if (p.video) {
      mediaHtml = `
        <div class="video-container">
          <video src="${esc(p.video)}" controls></video>
        </div>`;
    } else if (p.image) {
      const href = (p.links && p.links.demo) ? esc(p.links.demo) : '#';
      const rel  = (p.links && p.links.demo) ? ' target="_blank" rel="noopener noreferrer"' : '';
      mediaHtml = `
        <a href="${href}"${rel} class="image main">
          <img src="${esc(p.image)}" alt="${esc(p.title)}" />
        </a>`;
    }

    return `
      <article class="post featured">
        <header class="major">
          <span class="date">${esc(p.date)}</span>${statusPill(p.status)}
          <h2>${esc(p.title)}</h2>
          <p>${esc(p.description)}</p>
          ${renderBadges(p.model, p.accuracy, p.dataset)}
        </header>
        ${mediaHtml}
        ${renderLinks(p.links)}
      </article>`;
  }

  /* ── Grid project card ───────────────────────────────────── */

  function renderCard(p) {
    let mediaHtml;
    if (p.video) {
      mediaHtml = `
        <div class="video-container">
          <video src="${esc(p.video)}" controls></video>
        </div>`;
    } else if (p.image) {
      const href = (p.links && p.links.demo) ? esc(p.links.demo) : '#';
      const rel  = (p.links && p.links.demo) ? ' target="_blank" rel="noopener noreferrer"' : '';
      mediaHtml = `
        <a class="image fit" href="${href}"${rel}>
          <img src="${esc(p.image)}" alt="${esc(p.title)}" />
        </a>`;
    } else {
      mediaHtml = `<div class="img-placeholder">No Preview Yet</div>`;
    }

    return `
      <article>
        <header>
          <span class="date">${esc(p.date)}</span>${statusPill(p.status)}
          <h2>${esc(p.title)}</h2>
        </header>
        ${mediaHtml}
        ${renderBadges(p.model, p.accuracy, p.dataset)}
        <p>${esc(p.description)}</p>
        ${renderLinks(p.links)}
      </article>`;
  }

  /* ── Empty state ─────────────────────────────────────────── */

  function renderEmptyState() {
    return `
      <div class="empty-state">
        <i class="fas fa-layer-group"></i>
        <p>No projects added yet.</p>
        <p>Open <code>assets/js/projects-data.js</code> to add your first project.</p>
      </div>`;
  }

  /* ── Main render function ────────────────────────────────── */

  function renderCategory(categoryKey) {
    const data = (typeof PORTFOLIO !== 'undefined') && PORTFOLIO[categoryKey];
    if (!data) {
      console.warn('Portfolio: category "' + categoryKey + '" not found in projects-data.js');
      return;
    }

    /* Page title */
    document.title = data.pageTitle + ' — Visual Recognition Projects';

    /* Header logo */
    const logo = document.querySelector('#header .logo');
    if (logo) logo.textContent = data.pageTitle;

    /* Category intro paragraph */
    const introEl = document.getElementById('category-intro');
    if (introEl && data.intro) {
      introEl.innerHTML = '<p>' + esc(data.intro) + '</p>';
    }

    /* Featured card */
    const featuredEl = document.getElementById('featured-container');
    if (featuredEl) {
      featuredEl.innerHTML = renderFeatured(data.featured);
    }

    /* Project grid */
    const gridEl = document.getElementById('projects-grid');
    if (gridEl) {
      if (!data.projects || data.projects.length === 0) {
        gridEl.innerHTML = renderEmptyState();
      } else {
        gridEl.innerHTML = data.projects.map(renderCard).join('');
      }
    }
  }

  /* ── Boot: detect which page we are on and render ─────────── */

  document.addEventListener('DOMContentLoaded', function () {
    const root = document.querySelector('[data-category]');
    if (!root) return;
    renderCategory(root.dataset.category);
  });

})();
